#include <stdio.h>

double average(const int *values, int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) sum += values[i];
    return (double)sum / n;
}

int countAbove(const int *values, int n, double threshold) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] > threshold) count++;
    }
    return count;
}

int main(void) {
    int temps[7] = {21, 24, 19, 26, 23, 25, 20};
    double avg = average(temps, 7);
    printf("avg=%.2f\n", avg);
    printf("above=%d\n", countAbove(temps, 7, avg));
    return 0;
}

