#include <stdio.h>

enum Perm {
    PERM_READ = 1 << 0,
    PERM_WRITE = 1 << 1,
    PERM_EXEC = 1 << 2,
};

int has(int set, int flag) { return (set & flag) != 0; }

int main(void) {
    int perms = PERM_READ | PERM_EXEC;
    printf("read=%d write=%d exec=%d\n",
           has(perms, PERM_READ), has(perms, PERM_WRITE), has(perms, PERM_EXEC));
    perms |= PERM_WRITE;
    printf("after add write=%d\n", has(perms, PERM_WRITE));
    perms &= ~PERM_READ;
    printf("after remove read=%d\n", has(perms, PERM_READ));
    return 0;
}

