typedef struct {
    int data[4];
    int head, tail, count;
} Ring;

void push(Ring *r, int v) {
    if (r->count == 4) return;
    r->data[r->tail] = v;
    r->tail = (r->tail + 1) % 4;
    r->count++;
}
int pop(Ring *r, int *out) {
    if (r->count == 0) return 0;
    *out = r->data[r->head];
    r->head = (r->head + 1) % 4;
    r->count--;
    return 1;
}

int main(void) {
