#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    char key[16];
    int value;
    struct Entry *next;
} Entry;

#define BUCKETS 8

static unsigned hashOf(const char *s) {
    unsigned h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h % BUCKETS;
}

static void put(Entry **table, const char *key, int value) {
    unsigned b = hashOf(key);
    for (Entry *e = table[b]; e; e = e->next)
        if (strcmp(e->key, key) == 0) { e->value = value; return; }
    Entry *e = (Entry *)malloc(sizeof(Entry));
    strncpy(e->key, key, sizeof(e->key) - 1);
    e->key[sizeof(e->key) - 1] = '\0';
    e->value = value;
    e->next = table[b];
    table[b] = e;
}

static int *get(Entry **table, const char *key) {
    for (Entry *e = table[hashOf(key)]; e; e = e->next)
        if (strcmp(e->key, key) == 0) return &e->value;
    return NULL;
}

int main(void) {
    Entry *table[BUCKETS] = {0};
    put(table, "one", 1);
    put(table, "two", 2);
    put(table, "one", 100);
    int *v = get(table, "one");
    printf("one=%d\n", v ? *v : -1);
    printf("missing=%d\n", get(table, "nope") == NULL);
    for (int i = 0; i < BUCKETS; i++)
        for (Entry *e = table[i]; e; ) { Entry *n = e->next; free(e); e = n; }
    return 0;
}

