#include <stdio.h>

typedef enum { START, SIGN, DIGIT, ERROR, DONE } State;

int main(void) {
    const char *inputs[] = {"123", "-45", "+0", "-", "12x"};
    for (int k = 0; k < 5; k++) {
        State s = START;
        for (const char *p = inputs[k]; *p && s != ERROR; p++) {
            char c = *p;
            switch (s) {
                case START: s = (c == '+' || c == '-') ? SIGN : ((c >= '0' && c <= '9') ? DIGIT : ERROR); break;
                case SIGN: s = (c >= '0' && c <= '9') ? DIGIT : ERROR; break;
                case DIGIT: s = (c >= '0' && c <= '9') ? DIGIT : ERROR; break;
                default: break;
            }
        }
        int ok = (s == DIGIT) ? 1 : 0;
        printf("%s -> %s\n", inputs[k], ok ? "valid" : "invalid");
    }
    return 0;
}

