#include <stdio.h>
#include <stdlib.h>

typedef struct Stats Stats;
struct Stats { double *data; int size; int capacity; };

Stats *statsCreate(int cap) {
    Stats *s = (Stats *)malloc(sizeof(Stats));
    s->data = (double *)malloc((size_t)cap * sizeof(double));
    s->size = 0; s->capacity = cap;
    return s;
}
void statsAdd(Stats *s, double v) {
    if (s->size == s->capacity) {
        s->capacity *= 2;
        s->data = (double *)realloc(s->data, (size_t)s->capacity * sizeof(double));
    }
    s->data[s->size++] = v;
}
double statsMean(Stats *s) {
    double sum = 0;
    for (int i = 0; i < s->size; i++) sum += s->data[i];
    return sum / s->size;
}
double statsMax(Stats *s) {
    double m = s->data[0];
    for (int i = 1; i < s->size; i++) if (s->data[i] > m) m = s->data[i];
    return m;
}
void statsDestroy(Stats *s) { free(s->data); free(s); }

int main(void) {
    Stats *s = statsCreate(2);
    double values[] = {12.0, 7.5, 9.0, 15.0, 4.5};
    for (int i = 0; i < 5; i++) statsAdd(s, values[i]);
    printf("mean=%.2f\n", statsMean(s));
    printf("max=%.1f\n", statsMax(s));
    statsDestroy(s);
    return 0;
}

