typedef struct { char word[16]; int count; } WordCount;

int main(void) {
    const char *text = "the cat the dog the bird cat";
    WordCount counts[16];
    int n = 0;
    char buf[16];
    int bi = 0;
    for (int i = 0; ; i++) {
        char c = text[i];
        if (c == ' ' || c == '\0') {
            buf[bi] = '\0';
            if (bi > 0) {
                int found = -1;
                for (int j = 0; j < n; j++) if (strcmp(counts[j].word, buf) == 0) found = j;
                if (found < 0) { strcpy(counts[n].word, buf); counts[n].count = 1; n++; }
                else counts[found].count++;
            }
            bi = 0;
            if (c == '\0') break;
        } else if (bi < 15) {
            buf[bi++] = c;
        }
    }
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (counts[j].count < counts[j + 1].count) {
                WordCount t = counts[j]; counts[j] = counts[j + 1]; counts[j + 1] = t;
            }
    for (int i = 0; i < n; i++) printf("%s=%d\n", counts[i].word, counts[i].count);
    return 0;
}

