        size_ = other.size_;
        data_ = new char[size_ + 1];
        std::memcpy(data_, other.data_, size_ + 1);
    }
    ~Buffer() { delete[] data_; }
    std::size_t size() const { return size_; }
    const char* c_str() const { return data_; }
private:
    char* data_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    Buffer a("hello");
    Buffer b = a;
    b.c_str();
    std::cout << a.c_str() << " " << a.size() << "\n";
    std::cout << b.c_str() << " " << b.size() << "\n";
    return 0;
}

