#include <string>
#include <unordered_map>

class Inventory {
public:
    void add(const std::string& item, int count) { items_[item] += count; }
    std::optional<int> remove(const std::string& item, int count) {
        auto it = items_.find(item);
        if (it == items_.end() || it->second < count) return std::nullopt;
        it->second -= count;
        return it->second;
    }
    int total() const {
        int sum = 0;
        for (const auto& [item, count] : items_) sum += count;
        return sum;
    }
private:
    std::unordered_map<std::string, int> items_;
};

int main() {
    Inventory inv;
    inv.add("apple", 10);
    inv.add("pear", 5);
    if (auto left = inv.remove("apple", 3)) {
        std::cout << "apple left " << *left << "\n";
    }
    if (!inv.remove("pear", 100)) {
        std::cout << "pear insufficient\n";
    }
    std::cout << "total=" << inv.total() << "\n";
