#include <iostream>
#include <vector>

struct Ascending { static bool before(int a, int b) { return a < b; } };
struct Descending { static bool before(int a, int b) { return a > b; } };

template <typename Order>
void sortAndPrint(std::vector<int> v) {
    for (std::size_t i = 0; i + 1 < v.size(); ++i)
        for (std::size_t j = 0; j + 1 < v.size() - i; ++j)
            if (Order::before(v[j + 1], v[j])) std::swap(v[j], v[j + 1]);
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
}

int main() {
    sortAndPrint<Ascending>({3, 1, 2});
    sortAndPrint<Descending>({3, 1, 2});
    return 0;
}

#include <iostream>
#include <memory>
#include <string>

class AnyPrinter {
public:
    template <typename T>
    explicit AnyPrinter(T value)
        : impl_(std::make_unique<Model<T>>(std::move(value))) {}
    void print() const { impl_->print(); }
private:
    struct Concept {
        virtual ~Concept() = default;
        virtual void print() const = 0;
    };
    template <typename T>
    struct Model : Concept {
        explicit Model(T v) : value_(std::move(v)) {}
        void print() const override { std::cout << value_ << "\n"; }
        T value_;
    };
    std::unique_ptr<Concept> impl_;
};

int main() {
    AnyPrinter a(42);
    AnyPrinter b(std::string("hi"));
    a.print();
    b.print();
    return 0;
}

#include <cstddef>
#include <iostream>
#include <memory>
#include <vector>

template <typename T>
struct CountingAllocator {
    using value_type = T;
    CountingAllocator() = default;
    template <typename U>
    CountingAllocator(const CountingAllocator<U>&) {}
    T* allocate(std::size_t n) {
        ++allocations;
        return static_cast<T*>(::operator new(n * sizeof(T)));
    }
    void deallocate(T* p, std::size_t) { ::operator delete(p); }
    static inline int allocations = 0;
};

int main() {
    std::vector<int, CountingAllocator<int>> v;
    for (int i = 0; i < 100; ++i) v.push_back(i);
    std::cout << "size=" << v.size() << "\n";
    std::cout << "allocations>0=" << (CountingAllocator<int>::allocations > 0) << "\n";
    return 0;
}

#include <iostream>
#include <span>
#include <vector>

int sum(std::span<const int> data) {
    int total = 0;
    for (int x : data) total += x;
    return total;
}

int main() {
    int raw[] = {1, 2, 3};
    std::vector<int> v = {4, 5, 6, 7};
    std::cout << sum(raw) << "\n";
    std::cout << sum(v) << "\n";
    std::cout << sum(std::span(v).subspan(1, 2)) << "\n";
    return 0;
}

#include <iostream>
#include <ranges>
#include <vector>

int main() {
    std::vector<int> v = {1, 2, 3, 4, 5, 6};
    auto pipeline = v
        | std::views::filter([](int x) { return x % 2 == 0; })
        | std::views::transform([](int x) { return x * x; });
    for (int x : pipeline) std::cout << x << " ";
    std::cout << "\n";
    for (int x : pipeline | std::views::take(2)) std::cout << x << " ";
    std::cout << "\n";
    return 0;
}

