#include <iostream>
#include <thread>
#include <vector>

int main() {
    const int n = 4;
    std::vector<int> results(n, 0);
    std::vector<std::thread> workers;
    for (int i = 0; i < n; ++i) {
        workers.emplace_back([i, &results] { results[i] = (i + 1) * (i + 1); });
    }
    for (auto& t : workers) t.join();
    int sum = 0;
    for (int x : results) sum += x;
    std::cout << "sum=" << sum << "\n";
    return 0;
}

#include <condition_variable>
#include <iostream>
#include <mutex>
#include <queue>
#include <thread>

int main() {
    std::mutex m;
    std::condition_variable cv;
    std::queue<int> q;
    bool done = false;
    int total = 0;

    std::thread producer([&] {
        for (int i = 1; i <= 5; ++i) {
            {
                std::lock_guard<std::mutex> lock(m);
                q.push(i);
            }
            cv.notify_one();
        }
        {
            std::lock_guard<std::mutex> lock(m);
            done = true;
        }
        cv.notify_one();
    });

    std::thread consumer([&] {
        while (true) {
            std::unique_lock<std::mutex> lock(m);
            cv.wait(lock, [&] { return !q.empty() || done; });
            if (q.empty() && done) break;
            total += q.front();
            q.pop();
        }
    });

    producer.join();
    consumer.join();
    std::cout << "total=" << total << "\n";
    return 0;
}

#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

int main() {
    std::atomic<int> counter{0};
    std::vector<std::thread> workers;
    for (int t = 0; t < 4; ++t) {
        workers.emplace_back([&counter] {
            for (int i = 0; i < 1000; ++i)
                counter.fetch_add(1, std::memory_order_relaxed);
        });
    }
    for (auto& w : workers) w.join();
    std::cout << "counter=" << counter.load() << "\n";
    return 0;
}

