#include <iostream>
#include <string>
#include <utility>

class Config {
public:
    explicit Config(std::string name) : name_(std::move(name)) {}
    Config& operator=(Config other) {  // 传值：先拷贝
        swap(other);                   // 交换：不抛
        return *this;
    }
    void swap(Config& other) noexcept { std::swap(name_, other.name_); }
    const std::string& name() const { return name_; }
private:
    std::string name_;
};

int main() {
    Config a("first");
    Config b("second");
    a = b;
    std::cout << a.name() << " " << b.name() << "\n";
    return 0;
}

