#include <chrono>
#include <cstdint>
#include <iostream>

int main() {
    using clock = std::chrono::steady_clock;
    const auto start = clock::now();
    std::uint64_t sum = 0;
    for (int i = 0; i < 1000000; ++i) sum += static_cast<std::uint64_t>(i);
    const auto end = clock::now();
    const auto micros =
        std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    std::cout << "sum=" << sum << "\n";
    std::cout << "measured=" << (micros >= 0) << "\n";
    return 0;
}

