#include <iostream>
#include <memory>
#include <vector>

// 运行期多态：可在运行期选择实现
struct Operation {
    virtual ~Operation() = default;
    virtual int apply(int x) const = 0;
};
struct Double : Operation {
    int apply(int x) const override { return x * 2; }
};
struct Square : Operation {
    int apply(int x) const override { return x * x; }
};

// 编译期多态：零开销、可内联（函数对象而非类层次）
struct DoubleOp { int operator()(int x) const { return x * 2; } };
struct SquareOp { int operator()(int x) const { return x * x; } };

template <typename Op>
int applyStatic(int x) { return Op{}(x); }

int main() {
    std::vector<std::unique_ptr<Operation>> ops;
    ops.push_back(std::make_unique<Double>());
    ops.push_back(std::make_unique<Square>());
    for (const auto& op : ops) std::cout << op->apply(5) << " ";
    std::cout << "\n";
    std::cout << applyStatic<DoubleOp>(5) << " " << applyStatic<SquareOp>(5) << "\n";
    return 0;
}

