#include <cctype>
#include <iostream>
#include <memory>
#include <string>

struct Expr {
    virtual ~Expr() = default;
    virtual int eval() const = 0;
};
struct Num : Expr {
    explicit Num(int v) : value(v) {}
    int eval() const override { return value; }
    int value;
};
struct Add : Expr {
    Add(std::unique_ptr<Expr> l, std::unique_ptr<Expr> r)
        : left(std::move(l)), right(std::move(r)) {}
    int eval() const override { return left->eval() + right->eval(); }
    std::unique_ptr<Expr> left, right;
};
struct Mul : Expr {
    Mul(std::unique_ptr<Expr> l, std::unique_ptr<Expr> r)
        : left(std::move(l)), right(std::move(r)) {}
    int eval() const override { return left->eval() * right->eval(); }
    std::unique_ptr<Expr> left, right;
};

class Parser {
public:
    explicit Parser(const std::string& text) : s_(text) {}
    std::unique_ptr<Expr> parse() { return parseAdd(); }
private:
    std::unique_ptr<Expr> parseAdd() {
        auto node = parseMul();
        while (peek() == '+') { ++pos_; node = std::make_unique<Add>(std::move(node), parseMul()); }
        return node;
    }
    std::unique_ptr<Expr> parseMul() {
        auto node = parseAtom();
        while (peek() == '*') { ++pos_; node = std::make_unique<Mul>(std::move(node), parseAtom()); }
        return node;
    }
    std::unique_ptr<Expr> parseAtom() {
        if (peek() == '(') {
            ++pos_;
            auto node = parseAdd();
            ++pos_;  // skip )
            return node;
        }
        int value = 0;
        while (std::isdigit(static_cast<unsigned char>(peek()))) {
            value = value * 10 + (s_[pos_++] - '0');
        }
        return std::make_unique<Num>(value);
    }
    char peek() const { return pos_ < s_.size() ? s_[pos_] : '\0'; }
    std::string s_;
    std::size_t pos_ = 0;
};

int main() {
    Parser p("1+2*3");
    std::cout << p.parse()->eval() << "\n";
    Parser q("(1+2)*3");
    std::cout << q.parse()->eval() << "\n";
    return 0;
}
